115	function executionPrincipalsEqual(
116	  left: ParsedExecutionState["currentParticipant"] | null,
117	  right: ParsedExecutionState["currentParticipant"] | null,
118	) {
119	  if (!left || !right || left.type !== right.type) return false;
120	  return left.type === "agent" ? left.agentId === right.agentId : left.userId === right.userId;
121	}
