129	    wakeRole: input.wakeRole,
130	    stageId: input.state.currentStageId,
131	    stageType: input.state.currentStageType,
132	    currentParticipant: input.state.currentParticipant,
133	    returnAssignee: input.state.returnAssignee,
134	    reviewRequest: input.state.reviewRequest ?? null,
135	    lastDecisionOutcome: input.state.lastDecisionOutcome,
136	    allowedActions: input.allowedActions,
137	  };
138	}
